let criMode='Fentanyl';
const criUnits={'µg/kg/hr':.001,'µg/kg/min':.06,'mg/kg/hr':1,'mg/kg/min':60};
const criConfigs={Fentanyl:{prefix:'criF',unit:'µg',stock:50,doseUnit:'µg/kg/hr'},Ketamine:{prefix:'criK',unit:'mg',stock:100,doseUnit:'µg/kg/min'},Propofol:{prefix:'criP',unit:'mg',stock:10,doseUnit:'mg/kg/min'}};
const flkComponents=[{name:'Fentanyl',prefix:'flkF',unit:'µg',stock:50,doseUnit:'µg/kg/hr'},{name:'Lidocaine',prefix:'flkL',unit:'mg',stock:20,doseUnit:'µg/kg/min'},{name:'Ketamine',prefix:'flkK',unit:'mg',stock:100,doseUnit:'µg/kg/min'}];
// Normalize all doses and concentrations to mg/hr and mg/mL before arithmetic.
function criMgHour(weight,dose,unit){return positive(weight)&&positive(dose)&&Object.hasOwn(criUnits,unit)?Number(weight)*Number(dose)*criUnits[unit]:NaN}
function criMgMl(concentration,unit){return positive(concentration)&&['mg','µg'].includes(unit)?Number(concentration)*(unit==='µg'?.001:1):NaN}
function criPumpRate(weight,dose,doseUnit,concentration,concentrationUnit){return criMgHour(weight,dose,doseUnit)/criMgMl(concentration,concentrationUnit)}
function criPreparation(weight,pump,finalVolume,components){
 if(!positive(weight)||!positive(pump)||!positive(finalVolume))return {valid:false,reason:'Enter a positive patient weight, pump rate, and final volume.'};
 const values=components.map(c=>{const hourlyMg=criMgHour(weight,c.dose,c.doseUnit),stockMgMl=criMgMl(c.stock,c.unit),mgMl=hourlyMg/Number(pump);return {...c,hourlyMg,mgMl,drugVolume:mgMl*Number(finalVolume)/stockMgMl}});
 if(!values.length||values.some(c=>![c.hourlyMg,c.mgMl,c.drugVolume].every(v=>Number.isFinite(v)&&v>0)))return {valid:false,reason:'Enter a positive prescribed rate and stock concentration for every component.'};
 const stockVolume=values.reduce((v,c)=>v+c.drugVolume,0),carrier=Number(finalVolume)-stockVolume;
 if(carrier<0)return {valid:false,reason:'Drug volumes exceed the requested final volume. This preparation is not feasible; revise the prescribed setup.',values};
 return {valid:true,values,stockVolume,carrier,duration:Number(finalVolume)/Number(pump)};
}
function criUnitField(key,label,initial){if(!(key in data))data[key]=initial;return `<label>${label}<select data-cri-unit="${key}">${Object.keys(criUnits).map(u=>`<option ${data[key]===u?'selected':''}>${u}</option>`).join('')}</select></label>`}
function criDoseFields(c){return `<div class="formrow">${field(c.prefix+'Dose','Prescribed infusion rate','','see selected unit')}${criUnitField(c.prefix+'Unit','Dose units',c.doseUnit)}</div>`}
function criRead(c){return {name:c.name||criMode,dose:data[c.prefix+'Dose'],doseUnit:data[c.prefix+'Unit'],stock:data[c.prefix+'Stock'],unit:c.unit}}
function renderCri(){
 let h=head('Continuous rate infusion calculator','Prescribed-dose arithmetic · patient weight follows every calculation.')+`<div class="alert">No infusion doses or loading doses are prescribed by this calculator. Independently verify rate, units, concentration, pump setup, compatibility, sterility, line dead space, and monitoring. Changing a shared FLK pump rate changes all three delivered doses.</div><div class="criTabs" role="group" aria-label="CRI type">${['Fentanyl','FLK','Ketamine','Propofol'].map(name=>`<button class="outline ${criMode===name?'selected':''}" data-cri-mode="${name}" aria-pressed="${criMode===name}">${name} CRI</button>`).join('')}</div>`;
 if(criMode==='FLK'){
  h+=`<div class="alert">FLK = fentanyl + lidocaine + ketamine. This combined calculator is limited to dogs; a canine lidocaine protocol must not be extrapolated to cats. This tool does not establish admixture compatibility or stability.</div>`;
  if($('#species').value==='cat'){h+='<article class="card"><h3>FLK preparation unavailable for cats</h3><p>Use a veterinarian-selected feline protocol. Single-agent Fentanyl, Ketamine, and Propofol arithmetic remains available.</p></article>';$('#content').innerHTML=h;calculate();return;}
  h+=`<article class="card"><h3>Choose the final preparation</h3><div class="formrow">${field('flkPump','Prescribed shared pump rate','','mL/hr')}${field('flkVolume','FINAL combined preparation volume','','mL')}</div><p>Final volume includes all drug volumes plus carrier. It is not the starting bag volume.</p></article><div class="grid category">${flkComponents.map(c=>`<article class="card"><h3>${c.name}</h3>${criDoseFields(c)}${field(c.prefix+'Stock','Actual stock concentration',c.stock,c.unit+'/mL')}<p class="ref">${c.name==='Fentanyl'?'50 µg/mL = 0.05 mg/mL.':c.name==='Lidocaine'?'2% plain lidocaine = 20 mg/mL; confirm formulation suitable for IV administration without epinephrine.':'Verify ketamine formulation and route-specific dilution requirements.'}</p></article>`).join('')}</div><article class="card category"><h3>Combined preparation worksheet</h3><div id="flkResult" aria-live="polite"></div></article>`;
 }else{
  const c=criConfigs[criMode];h+=`<div class="grid"><article class="card"><span class="tag">PRESCRIBED RATE</span><h3>${criMode} CRI</h3>${criDoseFields(c)}${field(c.prefix+'Prepared','Actual concentration entering the pump',c.stock,c.unit+'/mL')}<p class="ref">Prefilled with a U.S. stock reference (${c.stock} ${c.unit}/mL). If diluted, replace it with the final syringe / bag concentration.</p>${result('criPumpResult')}</article><article class="card"><h3>Check the calculation</h3><p>mL/hr = weight × dose × time conversion ÷ concentration, with matching mass units.</p><div id="criCheck" class="ref"></div><p>Per-minute doses are multiplied by 60. 1 mg = 1000 µg. Changing dose units converts the entered rate to preserve the same dose.</p></article><article class="card"><h3>${criMode==='Propofol'?'Propofol handling':'Infusion review'}</h3><p>${criMode==='Propofol'?'Use an independently prepared propofol infusion. Do not mix propofol with other therapeutic agents in this calculator. Follow the exact product’s dilution, aseptic handling, and discard instructions.':'Confirm carrier compatibility, product-specific preparation instructions, pump accuracy, and the prescribed analgesia / anesthesia plan.'}</p><p>These tools calculate continuous delivery only. Loading doses, titration decisions, and line priming are separate clinical decisions.</p></article></div>`;
  if(criMode!=='Propofol')h+=`<article class="card category"><span class="tag">OPTIONAL · PREPARE TO A CHOSEN PUMP RATE</span><h3>${criMode} preparation planner</h3><div class="recordmeta">${field(c.prefix+'Stock','Actual stock concentration',c.stock,c.unit+'/mL')}${field(c.prefix+'Pump','Prescribed pump rate','','mL/hr')}${field(c.prefix+'Volume','FINAL preparation volume','','mL')}</div><p>Uses the prescribed dose above. This planner does not change the actual pump concentration field; enter the verified final concentration there after preparation.</p><div id="criPrepResult" aria-live="polite"></div></article>`;
 }
 h+=source('https://www.aaha.org/resources/2020-aaha-anesthesia-and-monitoring-guidelines-for-dogs-and-cats/phase-2-day-of-anesthesia/step-4-anesthetic-protocol/','AAHA · multimodal CRI context')+source('https://www.aaha.org/trends-magazine/publications/anesthesias-role-in-minimizing-the-cost-of-veterinary-care/','AAHA · canine systemic lidocaine context');
 const names=criMode==='FLK'?['Fentanyl','Lidocaine','Ketamine']:[criMode];h+='<div class="ref">Stock formulation references: '+names.map(name=>{const c=concentrationDefaults[name];return `<a target="_blank" rel="noopener" href="${c[2].startsWith('https:')?c[2]:labelUrl(c[2])}">${name} ↗</a>`}).join(' · ')+'</div>';
 if(criMode==='Propofol')h+=source('https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=fa93f173-7858-4d88-860e-76ab97e65c2f','Propofol label · preparation restrictions');
 $('#content').innerHTML=h;calculate();
}
function preparationHtml(r,pump,volume){
 if(!r.valid)return `<p class="alert">${r.reason}</p>`;
 return `<div class="tablewrap"><table class="criTable"><thead><tr><th>Component</th><th>Stock volume to withdraw</th><th>Final concentration</th><th>Delivery at ${fmt(Number(pump))} mL/hr</th></tr></thead><tbody>${r.values.map(c=>{const factor=c.unit==='µg'?1000:1,rate=c.hourlyMg/(kg()*criUnits[c.doseUnit]);return `<tr><th scope="row">${c.name}</th><td>${fmt(c.drugVolume)} mL${c.drugVolume<.01?'<br>Very small volume: verify measurement / dilution.':''}</td><td>${fmt(c.mgMl*factor)} ${c.unit}/mL</td><td>${fmt(rate)} ${c.doseUnit}</td></tr>`}).join('')}</tbody></table></div><div class="result">${r.carrier===0?'0':fmt(r.carrier)} mL carrier<small>Bring to FINAL ${fmt(Number(volume))} mL, including ${fmt(r.stockVolume)} mL total stock drugs.</small><small>At ${fmt(Number(pump))} mL/hr: ${fmt(r.duration)} hours theoretical duration, excluding line priming / losses.</small></div><p class="ref">Required mass = hourly dose × final volume ÷ pump rate. Stock volume = required mass ÷ stock concentration. Verify the admixture and label each drug, concentration, final volume, and pump rate.</p>`;
}
function calculateCri(){
 if(page!==8)return;
 if(criMode==='FLK'){if($('#species').value==='cat')return;const r=criPreparation(kg(),data.flkPump,data.flkVolume,flkComponents.map(criRead));if($('#flkResult'))$('#flkResult').innerHTML=preparationHtml(r,data.flkPump,data.flkVolume);return;}
 const c=criConfigs[criMode],dose=data[c.prefix+'Dose'],unit=data[c.prefix+'Unit'],prepared=data[c.prefix+'Prepared'],hourlyMg=criMgHour(kg(),dose,unit),pump=criPumpRate(kg(),dose,unit,prepared,c.unit);
 if($('#criPumpResult'))$('#criPumpResult').innerHTML=`${fmt(pump)} mL/hr<small>${fmt(hourlyMg*(c.unit==='µg'?1000:1))} ${c.unit}/hr ÷ ${positive(prepared)?fmt(Number(prepared)):'—'} ${c.unit}/mL</small>`;
 if($('#criCheck'))$('#criCheck').textContent=`Weight: ${fmt(kg())} kg. Prescribed rate: ${dose||'—'} ${unit}. Actual preparation: ${prepared||'—'} ${c.unit}/mL. Total: ${fmt(hourlyMg)} mg/hr.`;
 if(criMode!=='Propofol'&&$('#criPrepResult'))$('#criPrepResult').innerHTML=preparationHtml(criPreparation(kg(),data[c.prefix+'Pump'],data[c.prefix+'Volume'],[criRead(c)]),data[c.prefix+'Pump'],data[c.prefix+'Volume']);
}
document.addEventListener('click',e=>{if(e.target.dataset.criMode){criMode=e.target.dataset.criMode;render()}});
document.addEventListener('change',e=>{const key=e.target.dataset.criUnit;if(!key)return;const old=data[key],next=e.target.value,doseKey=key.replace(/Unit$/,'Dose');if(positive(data[doseKey])&&criUnits[old]&&criUnits[next])data[doseKey]=Number((Number(data[doseKey])*criUnits[old]/criUnits[next]).toPrecision(12));data[key]=next;render()});
